INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('3e7f46e1-e64a-43e3-a25f-891d91acaa35', '21feff02-016d-46e2-bb9d-c27495133b1b', '131. óra: Az oszthatóságról tanultak összefoglalása', 'Év végi ismétlés: oszthatósági szabályok, prímek, lkkt és lnko.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "377984f5-bdbb-4eb8-a135-e398c60948d9", "text": "Osztható-e a 435 5-tel és 3-mal is (azaz 15-tel)?", "type": "true-false", "options": [{"id": "c93e07c9-496f-4042-b38d-fcc879a55700", "text": "Igaz (5-re végződik és 4+3+5=12)", "isCorrect": true}, {"id": "fc899f35-b6a5-49fe-ad5e-441f62feab65", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ba622e1d-1529-4410-b7c5-1257e0f38247", "text": "Osztható-e a 612 4-gyel?", "type": "true-false", "options": [{"id": "81a9d6f4-f3a0-4b67-9aa4-f0b3115d9a38", "text": "Igaz (12 osztható 4-gyel)", "isCorrect": true}, {"id": "63b1bf15-8af4-47be-bcd8-a8f677c95f2d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "849867ef-5476-4aa8-8a9b-d98583f3912f", "text": "Mennyi lkkt(6, 8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "4b292a20-b8d2-4497-b812-33c2471be86a", "text": "Mennyi lnko(12, 18)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "c789882b-9e3d-41e7-bd8a-73e8703b44c9", "text": "Melyik a legkisebbkétjegyű prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "7a94beb1-0045-449c-ba4e-bba1566d55e2", "text": "A 2 az egyetlen páros prímszám.", "type": "true-false", "options": [{"id": "b0a25e7f-4a6f-44a1-af57-b87c1a566e6b", "text": "Igaz", "isCorrect": true}, {"id": "7a7feb49-9b95-485e-b06d-a8606bb60329", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ccbcb9de-9d89-46be-a17b-89beb5cc90ca", "text": "Melyik szám osztható 9-cel?", "type": "multiple-choice", "options": [{"id": "fa730324-648d-4cb0-a5c1-9c570b27cc08", "text": "819 (8+1+9=18)", "isCorrect": true}, {"id": "9b4601b2-f81f-4890-955e-8892d62d286e", "text": "815", "isCorrect": false}, {"id": "982fc224-d85e-4a00-8591-e6d4f5563c75", "text": "812", "isCorrect": false}, {"id": "5c9324cc-5c9e-46ec-959c-98cf023947f1", "text": "811", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b879c1a1-f8a9-441d-96e1-8c552f29270a', '21feff02-016d-46e2-bb9d-c27495133b1b', '132. óra: A törtekről tanultak összefoglalása, vegyes feladatok', 'Év végi ismétlés: közönséges és tizedes törtek műveletei.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "6fc5593f-d95a-41e2-9131-560c163dcb45", "text": "Mennyi 3/4 + 1/2? (3/4 + 2/4)", "type": "multiple-choice", "options": [{"id": "bd4905ee-e4a8-40ba-9282-c553cf520b95", "text": "5/4 (1 egész 1/4)", "isCorrect": true}, {"id": "53b2e0e8-9ce8-4e9f-8fb0-251be3419765", "text": "4/6", "isCorrect": false}, {"id": "d16c1176-ad59-4693-97a8-b57c7b6656ff", "text": "4/4", "isCorrect": false}, {"id": "d3c52e42-c82d-4eef-9d57-fc17d041ebaa", "text": "3/8", "isCorrect": false}], "timeLimit": 15}, {"id": "ed77b799-05a5-42cc-9e61-4168eb81e032", "text": "Mennyi 2/3 * 3/5?", "type": "multiple-choice", "options": [{"id": "dba4b5c0-7e6b-4f1c-a179-c02dd9067f3d", "text": "2/5", "isCorrect": true}, {"id": "f86c7039-7e15-44d0-832a-1e584be9e954", "text": "6/15", "isCorrect": false}, {"id": "93f5d233-ef9e-450d-8644-b0440f97dfa3", "text": "5/8", "isCorrect": false}, {"id": "91be792f-5b33-4199-896d-4063dac0d64b", "text": "6/8", "isCorrect": false}], "timeLimit": 15}, {"id": "a5aa24e3-04ef-49a9-a3c3-128ffb743980", "text": "Mennyi 1/2 : 1/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "33aeb6c6-2869-4831-aea8-b0094a7a0af4", "text": "Mennyi 2,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "a3ea50d4-7362-4cda-8739-70163d474c79", "text": "Mennyi 4,8 : 0,6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "e1b4e5fa-3335-4145-bcbd-22a038752220", "text": "A 0,75 megegyezik a 3/4 törttel.", "type": "true-false", "options": [{"id": "65ffd252-6bf3-497c-be66-2d45d16d47c6", "text": "Igaz", "isCorrect": true}, {"id": "b1a7fa19-acb1-4a51-ac99-76db9d832aab", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8fc4f3ed-9c28-45bd-8e14-eab21cd932e1", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('50535de8-d04c-49d3-a7db-7e979294dd22', '21feff02-016d-46e2-bb9d-c27495133b1b', '133. óra: A geometriai ismeretek összefoglalása, vegyes feladatok', 'Év végi ismétlés: szögek, alakzatok, tengelyes tükrözés.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "7cb52c47-5775-4001-bed2-850fdff12aea", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "75be77e5-8d96-4751-9346-7ff2504c13ec", "text": "Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "7bac0bb1-cf8a-4444-acd7-6426b8e0cea0", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "e9eecc67-a3c8-4961-8a2a-140b3c3b6100", "text": "Ha a kör sugara 6 cm, mekkora az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "6ac4fbfa-fb02-4f9f-8492-ea3fe11aae5f", "text": "A tengelyes tükrözés távolságtartó transzformáció.", "type": "true-false", "options": [{"id": "8eb4552b-ec1f-4af5-b714-89a54edc8883", "text": "Igaz", "isCorrect": true}, {"id": "26c5cf25-1275-4e46-8acc-6c3abcaf4290", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6db067b6-5f7f-45bf-91ca-1ed587c4d8f8", "text": "Hány fokos szöget zár be a szakaszfelező merőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "6d52666f-862b-456e-ade9-9fb0c878a618", "text": "Milyen szög a 90°-os szög?", "type": "multiple-choice", "options": [{"id": "a275f2a3-8814-45a1-8777-be50dd1e9511", "text": "Derékszög", "isCorrect": true}, {"id": "69b4565e-38b8-4a82-b214-aa5bed29c7f9", "text": "Hegyesszög", "isCorrect": false}, {"id": "7d528d29-1746-4b0b-a5f1-b1f347e3769d", "text": "Tompaszög", "isCorrect": false}, {"id": "50fd3628-2872-4c8f-a460-cd91579ad61f", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ba40bde3-f0b0-45d3-8963-4660501e80c0', '21feff02-016d-46e2-bb9d-c27495133b1b', '134. óra: Arányosság, százalék, szöveges feladatok', 'Év végi ismétlés: egyenes arányosság, százalékszámítás, nyitott mondatok.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "ca6f0ab7-7e54-4b40-986c-ee2d9e410601", "text": "Ossz el 500 Ft-ot 2 : 3 arányban! Hány Ft a kisebbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "0ed421f7-6853-4f8e-8f7a-bae724484369", "text": "Ha 3 kg narancs 1200 Ft, mennyibe kerül 7 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2800"}, {"id": "4a5ea23b-2d26-44e0-9e3e-307dec4a2143", "text": "Mennyi 4000 Ft-nak a 20%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "800"}, {"id": "47e32f96-460d-4249-8554-3c6ae1eb6827", "text": "Melyik szám teszi igazzá: 3 * x + 5 = 26? (21/3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "9560ab2f-d770-4a5f-8b23-8029f9f4bcab", "text": "Gondoltam egy számot, elosztottam 4-gyel, hozzáadtam 6-ot, 11-et kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "cfa08b06-36d8-4745-8412-8e8c2d76470a", "text": "Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "dba773f6-e86f-45c0-82ed-5b63e30cc261", "text": "Igaz", "isCorrect": true}, {"id": "77fd4ec2-425b-4e61-978c-1ce7e6c7e716", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "026a2118-8f9a-4f9f-90c6-5695821e97c1", "text": "Hány százalék felel meg a 4/5 törtszám teljes értékének?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "80"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ac1cf06e-b008-4d7e-9bc4-c673f46eb63e', '21feff02-016d-46e2-bb9d-c27495133b1b', '135. óra: A hosszúság, a kerület, a terület és a térfogat fogalmával kapcsolatos feladatok', 'Év végi ismétlés: mérések, kerület, terület, felszín, térfogat.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "af714570-110b-4f7f-a1ba-2020401d5b40", "text": "Mennyi a 6 cm és 5 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "2ac38b09-4997-4ad2-a7f9-ab24b95bb598", "text": "Mennyi a 6 cm és 5 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "cec948df-8585-4977-aef0-64786c32841d", "text": "Mennyi a 4 cm élű kocka felszíne? (6 * 16)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "489548d0-5e47-421a-916c-c975c77353a0", "text": "Mennyi a 4 cm élű kocka térfogata? (4 * 4 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "cc66ea5d-8ba2-48ab-bb7b-52565d001e3f", "text": "1 liter víz térfogata 1 dm³.", "type": "true-false", "options": [{"id": "b41275b4-8ba0-4825-8e1d-5735a7d8053a", "text": "Igaz", "isCorrect": true}, {"id": "64e171cb-6c29-488b-a5eb-96789f52e095", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "caa75efe-2163-419e-9aef-1b22743b7e40", "text": "Hány cm³ 1 dm³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "5d8df837-6f0a-4b88-8486-7f8ddd97ea40", "text": "Hány mm² 1 cm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('fe2850fc-01d3-47dc-8bad-dd7df71b1540', '21feff02-016d-46e2-bb9d-c27495133b1b', '136. óra: Az éves munka értékelése', 'Az 6. osztályos matematika törzsanyag sikeres teljesítésének záró értékelése.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "7678cabb-fb98-441f-a357-bda469c0e7c9", "text": "Mely főbb témaköröket dolgoztuk fel a 6. osztályos matematika tananyagban?", "type": "multiple-choice", "options": [{"id": "4a7d4b6c-138d-4f1b-81bd-67da8ae373e0", "text": "Egész számok, oszthatóság, törtek, geometria, arány és százalék, kerület-terület-felszín-térfogat, statisztika, pénzügyek", "isCorrect": true}, {"id": "72805ffd-f9fc-48ea-af76-b53aea779672", "text": "Kizárólag geometria", "isCorrect": false}, {"id": "fa6ddb91-b7f9-401c-a772-5381cf8face3", "text": "Kizárólag rajzolás", "isCorrect": false}, {"id": "aa1e3915-4388-47a3-b8ec-b646471a02a7", "text": "Csak az 1. osztályos ismétlés", "isCorrect": false}], "timeLimit": 15}, {"id": "adfbdce5-f13c-40b6-a018-345977dbb588", "text": "A szorgalmas felkészülés és a rendszerezett gyakorlás a matematikai tudás alapja.", "type": "true-false", "options": [{"id": "6db46f72-af05-4171-a9e9-2bb131a68e52", "text": "Igaz", "isCorrect": true}, {"id": "b4781850-005c-4b3c-bf08-9fc008ba9c4e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "71403ded-3ed7-4c9c-8b5f-36f0f3e2689b", "text": "Hány órából állt a 6. osztályos teljes matematika tananyag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "136"}, {"id": "3479109d-46d4-4f88-9c04-4dd25e8baf44", "text": "A megszerzett matematikai tudás segít a mindennapi pénzügyekben és a döntéshozatalban.", "type": "true-false", "options": [{"id": "ba47ae38-0af3-406d-b4b9-675bf7ac38d7", "text": "Igaz", "isCorrect": true}, {"id": "be56115d-248b-443c-989c-06d14f3afd2d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "31290ee0-e86e-488b-9902-80ac76723b54", "text": "Gratulálunk a 6. osztályos matematika tananyag sikeres teljesítéséhez!", "type": "true-false", "options": [{"id": "05f33927-87af-4246-bd00-8d01eb8bcbde", "text": "Igaz", "isCorrect": true}, {"id": "63dcfb28-9651-47d6-aef7-45a8b3fc160f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "eaba0429-2d3b-4deb-adb6-f59768624c99", "text": "A 7. osztályban az itt megszerzett alapokra (pl. oszthatóság, törtek, százalék, geometria) építünk tovább.", "type": "true-false", "options": [{"id": "ef55175a-7c63-4f9e-beb2-e6a09f7440e3", "text": "Igaz", "isCorrect": true}, {"id": "bfa03a80-962c-4715-9e36-004c2be96856", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6f19ee86-549c-42a9-ae3f-a1ec064d47eb", "text": "Melyik volt a kedvenc témaköröd ebben a tanévben?", "type": "multiple-choice", "options": [{"id": "9406f3e3-5d96-445c-b844-b9ddfeb40bfa", "text": "Mindegyik témakör hasznos és érdekes volt!", "isCorrect": true}, {"id": "51f4cad8-10dd-4d52-8ce4-e24e6e17b875", "text": "Egész számok és oszthatóság", "isCorrect": false}, {"id": "ff4f91d5-f3ee-4488-8d75-7a120ee8e584", "text": "Geometria és tengelyes tükrözés", "isCorrect": false}, {"id": "ea21383a-8586-43fd-8d24-20e9024e9d6b", "text": "Arányosság és százalékszámítás", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;